#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string s;
    cin >> s;

    int removed = 0;
    bool changed = true;

    // We try to remove characters starting from 'z' down to 'b'
    while (changed) {
        changed = false;
        for (char c = 'z'; c >= 'b'; --c) {
            bool localChange = true;
            while (localChange) {
                localChange = false;
                for (int i = 0; i < (int)s.size(); ++i) {
                    if (s[i] == c) {
                        bool canRemove = false;
                        if (i > 0 && s[i - 1] == c - 1) canRemove = true;
                        if (i + 1 < (int)s.size() && s[i + 1] == c - 1) canRemove = true;
                        if (canRemove) {
                            s.erase(s.begin() + i);
                            ++removed;
                            localChange = true;
                            changed = true;
                            break;
                        }
                    }
                }
            }
        }
    }

    cout << removed << '\n';
    return 0;
}

